WITH valid_orders AS (SELECT member_id, ordered_at, paid_cents - refund_cents AS net_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), base AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS valid_order_cnt, SUM(net_cents) AS net_cents FROM valid_orders GROUP BY member_id, CAST(date_trunc('month', ordered_at) AS DATE)), eligible AS (SELECT DISTINCT o.member_id, last_day(o.ordered_at) AS month_end_date FROM {{ ref('orders') }} o WHERE EXISTS (SELECT 1 FROM {{ ref('cards') }} c WHERE c.member_id = o.member_id AND c.card_type IN ('悦享年卡', '家庭季卡') AND c.valid_from <= last_day(o.ordered_at) AND last_day(o.ordered_at) < c.valid_until AND (c.ended_at IS NULL OR c.ended_at > last_day(o.ordered_at)))) SELECT b.member_id || '|' || CAST(b.month_start AS VARCHAR) AS member_month, b.member_id, b.month_start, b.valid_order_cnt, b.net_cents, (e.member_id IS NOT NULL) AS is_paid_eligible FROM base b LEFT JOIN eligible e ON b.member_id = e.member_id AND last_day(b.month_start) = e.month_end_date